// DecodeUpdateConversationRequest returns a decoder for requests sent to the
// ai updateConversation endpoint.
func DecodeUpdateConversationRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*ai.UpdateConversationPayload, error) {
	return func(r *http.Request) (*ai.UpdateConversationPayload, error) {
		var payload *ai.UpdateConversationPayload
		var (
			body UpdateConversationRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateUpdateConversationRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			sessionID string
			cookie    string

			params = mux.Vars(r)
		)
		sessionID = params["sessionId"]
		if utf8.RuneCountInString(sessionID) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("sessionId", sessionID, utf8.RuneCountInString(sessionID), 1, true))
		}
		if utf8.RuneCountInString(sessionID) > 80 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("sessionId", sessionID, utf8.RuneCountInString(sessionID), 80, false))
		}
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewUpdateConversationPayload(&body, sessionID, cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

