// marshalAiCapabilityInvocationToCapabilityInvocation builds a value of type
// *CapabilityInvocation from a value of type *ai.CapabilityInvocation.
func marshalAiCapabilityInvocationToCapabilityInvocation(v *ai.CapabilityInvocation) *CapabilityInvocation {
	res := &CapabilityInvocation{
		InvocationID:  v.InvocationID,
		Capability:    v.Capability,
		Version:       v.Version,
		Origin:        v.Origin,
		Status:        v.Status,
		Input:         v.Input,
		InputDigest:   v.InputDigest,
		Result:        v.Result,
		ErrorCode:     v.ErrorCode,
		ApprovalID:    v.ApprovalID,
		CorrelationID: v.CorrelationID,
		CausationID:   v.CausationID,
		TriggerDepth:  v.TriggerDepth,
		DurationMs:    v.DurationMs,
		TraceID:       v.TraceID,
		CreatedAt:     v.CreatedAt,
		FinishedAt:    v.FinishedAt,
	}

	return res
}

// marshalAiAIRunToAIRunResponse builds a value of type *AIRunResponse from a
// value of type *ai.AIRun.
func marshalAiAIRunToAIRunResponse(v *ai.AIRun) *AIRunResponse {
	res := &AIRunResponse{
		ID:                 v.ID,
		Question:           v.Question,
		Answer:             v.Answer,
		Status:             v.Status,
		Agent:              v.Agent,
		Model:              v.Model,
		InstructionVersion: v.InstructionVersion,
		Origin:             v.Origin,
		ErrorCode:          v.ErrorCode,
		ToolCalls:          v.ToolCalls,
		PromptTokens:       v.PromptTokens,
		CompletionTokens:   v.CompletionTokens,
		DurationMs:         v.DurationMs,
		TraceID:            v.TraceID,
		CorrelationID:      v.CorrelationID,
		CausationID:        v.CausationID,
		TriggerDepth:       v.TriggerDepth,
		TriggerPolicy:      v.TriggerPolicy,
		EventID:            v.EventID,
		CreatedAt:          v.CreatedAt,
		FinishedAt:         v.FinishedAt,
	}
	if v.Invocations != nil {
		res.Invocations = make([]*CapabilityInvocation, len(v.Invocations))
		for i, val := range v.Invocations {
			if val == nil {
				res.Invocations[i] = nil
				continue
			}
			res.Invocations[i] = marshalAiCapabilityInvocationToCapabilityInvocation(val)
		}
	} else {
		res.Invocations = []*CapabilityInvocation{}
	}

	return res
}

